from lib import *
chapter(7,'maths','large-numbers-around-us','Large Numbers Around Us',
 ('Counting a crowd','A cricket ground holds a lakh people. India has more than a hundred crore people. Numbers this big appear in news every day. How do we read, write and compare them?'),
 [('Lakhs, crores and millions',['In the Indian system, we group digits as ones, tens, hundreds, thousands, then lakhs and crores.','One lakh is 1,00,000. One crore is 1,00,00,000, which is 100 lakhs.','In the international system, we use millions. One million is 10 lakhs.','So one crore equals ten million.']),
  ('Reading and writing',['Use commas to read large numbers. In the Indian system the first comma is after three digits from the right, then after every two digits.','The number 2,45,67,890 is read: two crore forty-five lakh sixty-seven thousand eight hundred and ninety.','Place value helps: the digit 4 in 2,45,67,890 is in the ten lakhs place.']),
  ('Comparing large numbers',['First compare the number of digits. The number with more digits is larger.','If the digit counts are equal, compare from the leftmost digit.']),
  ('Exact and approximate values',['Sometimes we need only an estimate. We round a number to the nearest lakh or crore.','Population figures are usually rounded because they change every day.','Large numbers are built from patterns: 1 crore is 100 lakhs.'])],
 [('Write 3 crore 5 lakh 40 thousand in numbers.',[('3 crore is 3,00,00,000.','Write each place.'),('Add 5 lakh and 40 thousand to get 3,05,40,000.','Combine.')]),
  ('Round 4,67,382 to the nearest lakh.',[('The lakh digit is 4 and the next digit is 6.','Look at the next place.'),('6 is 5 or more so round up to 5,00,000.','Round up.')])],
 ('Explain how many lakhs make a crore.',['1 crore is 100 lakhs.','Each place is 10 times the one on its right.'],['Placing commas in groups of three.','Thinking a crore is 10 lakhs.']),
 ['In the Indian system: ones, tens, hundreds, thousands, lakhs, crores.','1 lakh = 1,00,000; 1 crore = 100 lakhs.','1 million = 10 lakh; 1 crore = 10 million.','Compare by number of digits, then from the left.'],
 [num('l1-1',1,'How many lakhs make one crore?',100,'1 crore = 1,00,00,000 and 1 lakh = 1,00,000.',[(10,'10 lakhs make one million.')]),
  mcq('l1-2',1,'1,00,000 is','one lakh',[('ten thousand','That has 5 digits.'),('one crore','A crore has 8 digits.')],'Six digits starting with 1.'),
  mcq('l1-3',1,'Which is larger?','12,34,567',[('9,87,654','This has one digit fewer.'),('99,999','Only 5 digits.')],'More digits means larger.'),
  num('l1-4',1,'One crore equals how many millions?',10,'1 crore is ten million.',[(100,'That is lakhs.')],'million'),
  mcq('l1-5',2,'Round 4,67,382 to the nearest lakh','5,00,000',[('4,00,000','Next digit is 6, so round up.'),('4,70,000','That is rounding to ten thousands.')],'6 is 5 or more.'),
  mcq('l1-6',2,'The digit 4 in 2,45,67,890 is in the','ten lakhs place',[('lakhs place','The lakhs place is 5.'),('crores place','Crores place is 2.')],'Counting from the right.'),
  num('l1-7',2,'In 3,05,40,000 what is the digit in the lakhs place?',5,'After the crore comes 0 ten lakh then 5 lakh.',[(0,'0 is ten lakhs.')]),
  tf('l1-8',2,'The Indian system places the first comma after three digits from the right.',True,'Then after every two digits.'),
  mcq('l1-9',3,'1 million is the same as','10 lakhs',[('1 lakh','A lakh is smaller.'),('1 crore','1 crore is ten million.')],'10,00,000.'),
  mcq('l1-10',3,'Why do we round population figures?','They change every day',[('To make them wrong','Rounding keeps the idea.'),('To use fewer digits only','The reason is that exact values keep changing.')],'An estimate is enough.')],
 keep=['lakh','crore','million'])
chapter(7,'maths','arithmetic-expressions','Arithmetic Expressions',
 ('Who is right?','Ravi says 2 plus 3 times 4 is 20. Meena says it is 14. Both did correct arithmetic but in a different order. We need rules about what to do first.'),
 [('Order of operations',['An expression is a combination of numbers and operations like add, subtract, multiply and divide.','Follow the order: brackets first, then multiplication and division from left to right, then addition and subtraction from left to right.','So 2 plus 3 times 4 equals 2 plus 12, which is 14.']),
  ('Brackets',['Brackets change the order. In (2 plus 3) times 4, we add first and get 20.','When there are brackets inside brackets, work from the innermost one outwards.']),
  ('Terms, swapping and grouping',['The parts joined by plus or minus are called terms.','Addition can be swapped and regrouped: 5 plus 3 equals 3 plus 5, and (2 plus 3) plus 4 equals 2 plus (3 plus 4).','Multiplication can also be swapped and regrouped. Subtraction and division cannot.','Brackets can be opened using the rule a times (b plus c) equals a times b plus a times c.'])],
 [('Evaluate 8 + 6 x 3 - 4.',[('Multiply first: 6 times 3 is 18.','Multiplication before addition.'),('8 plus 18 minus 4 equals 22.','Then go left to right.')]),
  ('Evaluate (5 + 3) x (10 - 4).',[('Brackets first: 8 and 6.','Do each bracket.'),('8 times 6 is 48.','Then multiply.')])],
 ('A friend says 10 minus 4 plus 2 is 4. Explain the mistake.',['Go left to right: 10 minus 4 is 6 then plus 2 gives 8.'],['Doing addition before subtraction.','Ignoring brackets.']),
 ['Brackets first, then times and divide, then add and subtract.','Brackets change the order.','Addition and multiplication can be swapped and regrouped.','Subtraction and division cannot be swapped.'],
 [num('x2-1',1,'2 + 3 x 4 = ?',14,'Multiply first: 12; then add 2.',[(20,'That adds first, which is wrong.')]),
  num('x2-2',1,'(2 + 3) x 4 = ?',20,'Bracket first: 5 times 4.',[(14,'The bracket forces addition first.')]),
  tf('x2-3',1,'Subtraction can be swapped: 5 - 3 = 3 - 5.',False,'5 minus 3 is 2 but 3 minus 5 is not 2.'),
  mcq('x2-4',1,'What is done first in 6 + 8 / 2?','8 / 2',[('6 + 8','Division comes before addition.'),('all together','There is a fixed order.')],'Division before addition.'),
  num('x2-5',2,'10 - 4 + 2 = ?',8,'Left to right.',[(4,'Do not add 4 and 2 first.')]),
  num('x2-6',2,'(5 + 3) x (10 - 4) = ?',48,'8 times 6.',[(14,'Do not add the results.')]),
  num('x2-7',2,'8 + 6 x 3 - 4 = ?',22,'6 times 3 is 18; 8 plus 18 is 26; 26 minus 4 is 22.',[(38,'Multiplication comes first.')]),
  mcq('x2-8',2,'a x (b + c) equals','a x b + a x c',[('a x b + c','Multiply a with both b and c.'),('a + b x c','The bracket is not respected.')],'Opening the brackets.'),
  num('x2-9',3,'20 / (2 + 3) x 2 = ?',8,'20 / 5 is 4, times 2 is 8.',[(2,'Go left to right after the bracket.')]),
  mcq('x2-10',3,'Which of these can be swapped?','Addition',[('Subtraction','5 - 3 is not 3 - 5.'),('Division','6 / 3 is not 3 / 6.')],'Addition and multiplication are commutative.')],
 keep=['expression','bracket','term'])
